      else break;
      continue;
    }
    if (state.phase !== 'prep' && state.phase !== 'wave') break;
    const step = Math.min(1 / 60, remaining);
    updatePlay(step);
    remaining -= step;
  }
  return {
    phase: state.phase, wave: state.wave, elapsed: state.elapsed,
    enemies: state.enemies.length, hp: state.sanctuaryHp,
