  state.speed = 1;
  debugFill();
  let safety = 0;
  while (state.wave <= maxWave && safety < 80) {
    safety++;
    if (state.phase === 'victory' || state.phase === 'defeat') break;
    if (state.phase === 'prep') {
      debugUpgrade();
