playwright-cli -s=cov eval "() => { const c=window.__covenant; c.start(); const types=['ember','serpent','ballista','seal']; const log=[]; function buy(){ let guard=true; while(guard){ guard=false; for(const t of types){ const def=c.state; } } } const data=[];
  // Build first three affordable
  c.build('ember',0); c.build('ember',1); c.build('serpent',2);
  for(let w=1; w<=20; w++){
    if(c.state.phase==='defeat'||c.state.phase==='victory') break;
    // prep purchases
    let bought=true;
    while(bought){
      bought=false;
      const s=c.state;
      // add tower if free pad and affordable
      const order=['ballista','serpent','ember','seal','ember','serpent','ballista','seal','ember','serpent','ballista','seal'];
      for(let i=0;i<12;i++){
        const pad=s.pads[i];
        if(!pad.towerId && s.gold>=140 && i>=3){ c.build(order[i%4],i); bought=true; break; }
      }
      if(!bought){ for(let i=0;i<4;i++){ const sp=s.sanctum[i]; if(!sp.econId && s.gold>=60){ c.build(i===0?'well':i===1?'reliquary':'oracle',i); bought=true; break; } } }
    }
    // upgrade a tower
    if(c.state.towers.length){ const t=c.state.towers[0]; if(t.level<4 && c.state.gold>=200) c.upgrade(); }
    c.startWave();
    let guard=0;
    while(c.state.phase==='wave' && guard<300){ c.advance(1); guard++; }
    data.push({w:c.state.wave, phase:c.state.phase, hp:c.state.sanctuaryHp, gold:Math.round(c.state.gold), towers:c.state.towers.length, econ:c.state.economy.length, kills:c.state.kills});
  }
  return data;
}" 2>&1 | head -120

